mapper.select:
SELECT h.id, h.product_id, p.product_code, p.title AS product_title, h.deal_id, h.price, h.currency, h.source_type, h.source_name, h.verification_status, h.recorded_at, h.verified_by, u.display_name AS verifier_name, h.note FROM price_history h JOIN product p ON p.id = h.product_id LEFT JOIN admin_user u ON u.id = h.verified_by
AND h.product_id = #{productId} AND h.deal_id = #{dealId}
ORDER BY h.recorded_at DESC, h.id DESC
